package com.deepseatrawling;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PluginLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DeepSeaTrawling.class);
		RuneLite.main(args);
	}
}

package com.deepseatrawling;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

import javax.inject.Singleton;
import java.io.IOException;
import java.io.InputStream;
import java.util.*;
import java.util.stream.Collectors;

@Slf4j
@Singleton
public class ShoalRouteRegistry
{
    private static final String RESOURCE_NAME = "shoals.properties";

    @Getter
    private final Map<Integer, ShoalRoute> routesByWorldViewId = new HashMap<>();

    public void load() throws IOException
    {
        routesByWorldViewId.clear();

        Properties props = new Properties();
        try (InputStream in = getClass().getResourceAsStream("/" + RESOURCE_NAME))
        {
            if (in == null)
            {
                throw new IOException("Could not find resource: " + RESOURCE_NAME);
            }
            props.load(in);
        }

        // Temporary accumulators so order doesn't matter
        Map<Integer, List<WorldPoint>> paths = new HashMap<>();
        Map<Integer, List<WorldPoint>> stops = new HashMap<>();

        for (String key : props.stringPropertyNames())
        {
            String value = props.getProperty(key);

            if (key.startsWith("shoalpath."))
            {
                int id = Integer.parseInt(key.substring("shoalpath.".length()));
                paths.put(id, parsePoints(value));
            }
            else if (key.startsWith("shoalstops."))
            {
                int id = Integer.parseInt(key.substring("shoalstops.".length()));
                stops.put(id, parsePoints(value));
            }
        }

        // Merge into final routes map
        Set<Integer> allIds = new HashSet<>();
        allIds.addAll(paths.keySet());
        allIds.addAll(stops.keySet());

        for (int id : allIds)
        {
            List<WorldPoint> p = paths.getOrDefault(id, List.of());
            List<WorldPoint> s = stops.getOrDefault(id, List.of());
            routesByWorldViewId.put(id, new ShoalRoute(p, s));
        }

        log.info("Loaded {} shoal routes from {}", routesByWorldViewId.size(), RESOURCE_NAME);
    }

    public ShoalRoute get(int worldViewId)
    {
        return routesByWorldViewId.getOrDefault(worldViewId, ShoalRoute.EMPTY);
    }

    private List<WorldPoint> parsePoints(String value)
    {
        if (value == null || value.trim().isEmpty())
        {
            return List.of();
        }

        return Arrays.stream(value.split("\\|"))
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .map(this::parsePoint)
                .collect(Collectors.toList());
    }

    private WorldPoint parsePoint(String token)
    {
        String[] parts = token.split(",\\s*");
        if (parts.length < 3)
        {
            throw new IllegalArgumentException("Invalid point token: " + token);
        }

        int x = Integer.parseInt(parts[0].trim());
        int y = Integer.parseInt(parts[1].trim());
        int plane = Integer.parseInt(parts[2].trim());
        return new WorldPoint(x, y, plane);
    }
}

package com.deepseatrawling;

import java.util.*;

import lombok.Getter;
import lombok.Setter;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.WorldEntity;
import net.runelite.api.coords.WorldPoint;

public class ShoalData {

    public enum ShoalSpecies
    {
        GIANT_KRILL (ObjectID.SAILING_SHOAL_CLICKBOX_GIANT_KRILL, 32309),
        HADDOCK (ObjectID.SAILING_SHOAL_CLICKBOX_HADDOCK, 32317),
        YELLOWFIN (ObjectID.SAILING_SHOAL_CLICKBOX_YELLOWFIN, 32325),
        HALIBUT (ObjectID.SAILING_SHOAL_CLICKBOX_HALIBUT, 32333),
        BLUEFIN (ObjectID.SAILING_SHOAL_CLICKBOX_BLUEFIN, 32341),
        MARLIN (ObjectID.SAILING_SHOAL_CLICKBOX_MARLIN, 32349),
        SHIMMERING (ObjectID.SAILING_SHOAL_CLICKBOX_SHIMMERING, -1),
        GLISTENING (ObjectID.SAILING_SHOAL_CLICKBOX_GLISTENING, -1),
        VIBRANT (ObjectID.SAILING_SHOAL_CLICKBOX_VIBRANT, -1);

        private final int objectID;
        private final int itemID;

        public ShoalDepth defaultDepth()
        {
            switch (this)
            {
                case GIANT_KRILL:
                case HADDOCK:
                case SHIMMERING:
                    return ShoalDepth.SHALLOW;
                default:
                    return ShoalDepth.MEDIUM;
            }
        }

        ShoalSpecies(int objectID, int itemID) {
            this.objectID = objectID;
            this.itemID = itemID;
        }

        public int getItemID() {
            return itemID;
        }

        public static ShoalSpecies fromGameObjectId(int id)
        {
            for (ShoalSpecies s : values())
            {
                if (s.objectID == id) {
                    return s;
                }
            }
            return null;
        }

        public static ShoalSpecies fromFishName(String fishName)
        {
            String normalized = fishName.toLowerCase();
            if (normalized.contains("krill")) {
                return GIANT_KRILL;
            } else if (normalized.contains("haddock")) {
                return HADDOCK;
            } else if (normalized.contains("yellowfin")) {
                return YELLOWFIN;
            } else if (normalized.contains("halibut")) {
                return HALIBUT;
            } else if (normalized.contains("bluefin")) {
                return BLUEFIN;
            } else if (normalized.contains("marlin")) {
                return MARLIN;
            }
            return null;
        }

    }

    public enum ShoalDepth
    {
        SHALLOW,
        MEDIUM,
        DEEP,
        UNKNOWN;

        public static int asInt(ShoalDepth depth)
        {
			if (depth == null) {
				return -1;
			}
            switch(depth) {
                case SHALLOW:
                    return 1;
                case MEDIUM:
                    return 2;
                case DEEP:
                    return 3;
                default:
                    return -1;
            }
        }
    }

    public static Map<ShoalSpecies, Integer> shoalTimers = Map.of(
            ShoalSpecies.GIANT_KRILL, 150,
            ShoalSpecies.HADDOCK, 120,
            ShoalSpecies.YELLOWFIN, 100,
            ShoalSpecies.HALIBUT, 80,
            ShoalSpecies.BLUEFIN, 70,
            ShoalSpecies.MARLIN, 50
    );

    private int stopStartTick = -1;
    private int stopDurationTicks = 0; // set when stop begins

    @Setter
    @Getter
    private NPC shoalNpc;

    @Getter
    @Setter
    private ShoalDepth depth;

    @Getter
    private final WorldEntity worldEntity;

    @Getter
    private final int worldViewId;

    @Setter
    @Getter
    private ShoalSpecies species;

    @Setter
    @Getter
    private GameObject shoalObject;

    @Getter
    @Setter
    private WorldPoint last;

    @Getter
    @Setter
    private WorldPoint currentWorldPoint;

    @Setter
    @Getter
    private boolean wasMoving;

    @Getter
    @Setter
    private int movingStreak = 0;

    @Getter
    @Setter
    private int stoppedStreak = 0;

    /*
    public void setNext(LocalPoint next) {
        this.next = next;
    }

    public void setPathPoints(WorldPoint worldPoint) {
            pathPoints.add(worldPoint);
    }

    public void setStopPoints(WorldPoint worldPoint) {
        if(stopPoints.contains(worldPoint))
        {
            return;
        }
        stopPoints.add(worldPoint);
    }
*/
    @Getter
    private final List<WorldPoint> pathPoints;
    @Getter
    private final List<WorldPoint> stopPoints;

    public ShoalData(int worldViewId, WorldEntity worldEntity, ShoalRoute route) {
        this.worldViewId = worldViewId;
        this.worldEntity = worldEntity;
        this.pathPoints = route.getPathPoints();
        this.stopPoints = route.getStopPoints();
    }

    public void setDepthFromAnimation(int currentTick)
    {
        if (shoalNpc == null)
        {
            if (getTicksUntilMove(currentTick) > 0 && getTicksUntilDepthChange(currentTick) > 0) {
                this.depth = ShoalDepth.UNKNOWN;
            } else {
                this.depth = this.species.defaultDepth();
            }
            return;
        }
        int animation = shoalNpc.getAnimation();
        if (animation == -1)
        {
            return;
        }

        switch (animation)
        {
			case AnimationID.DEEP_SEA_TRAWLING_SHOAL_SHALLOW:
                this.depth = ShoalDepth.SHALLOW;
                break;
            case AnimationID.DEEP_SEA_TRAWLING_SHOAL_MID:
                this.depth = ShoalDepth.MEDIUM;
                break;
            case AnimationID.DEEP_SEA_TRAWLING_SHOAL_DEEP:
                this.depth = ShoalDepth.DEEP;
                break;
            default:
                this.depth = ShoalDepth.UNKNOWN;

        }

    }

    public void beginStopTimer(int currentTick, int durationTicks)
    {
        this.stopStartTick = currentTick;
        this.stopDurationTicks = durationTicks;
    }

    public void clearStopTimer()
    {
        this.stopStartTick = -1;
        this.stopDurationTicks = 0;
    }

    public boolean hasActiveStopTimer()
    {
        return stopStartTick >= 0 && stopDurationTicks > 0;
    }

    public int getTicksUntilMove(int currentTick)
    {
        if (!hasActiveStopTimer()) return -1;
        int elapsed = currentTick - stopStartTick;
        return Math.max(0, stopDurationTicks - elapsed);
    }

    public int getTicksUntilDepthChange(int currentTick)
    {
        if (!hasActiveStopTimer()) return -1;
        if (this.getSpecies() == ShoalSpecies.GIANT_KRILL || this.getSpecies() == ShoalSpecies.HADDOCK || this.getSpecies() == ShoalSpecies.SHIMMERING) { return -1; }
        int half = stopDurationTicks / 2;
        int elapsed = currentTick - stopStartTick;
        return Math.max(-1, half - elapsed);
    }

/*
    public boolean isPastDepthChangePoint(int currentTick)
    {
        if (!hasActiveStopTimer()) return false;
        int half = stopDurationTicks / 2;
        return (currentTick - stopStartTick) >= half;
    }
*/


}

package com.deepseatrawling;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;

public class DeepSeaTrawlingWidgetOverlay extends Overlay {

    private static final int SAILING_SIDEPANEL_GROUP = 937;
    private static final int FACILITIES_CONTENT_CLICKLAYER_CHILD = 25;

    private static final int SKIFF_DOWN_INDEX = 29;
    private static final int SKIFF_UP_INDEX = 30;
    private static final int STARBOARD_DOWN_INDEX = 41;
    private static final int STARBOARD_UP_INDEX = 42;
    private static final int PORT_DOWN_INDEX = 45;
    private static final int PORT_UP_INDEX = 46;

    private static final int SKIFF_WORLDVIEW_ID = 2;
    private static final int SLOOP_WORLDVIEW_ID = 3;

    private final Client client;
    private final DeepSeaTrawling plugin;

    @Inject
    DeepSeaTrawlingConfig config;

    enum Direction {
        UP,
        DOWN
    }

    @Inject
    public DeepSeaTrawlingWidgetOverlay(Client client, DeepSeaTrawling plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    private Integer getPlayerBoatType() {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || localPlayer.getWorldView() == null) return null;
        return plugin.boats.get(localPlayer.getWorldView().getId());
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Integer playerBoat = getPlayerBoatType();
        if (playerBoat != null) {
            if (config.showNetDepthText()) {
                if (playerBoat == SKIFF_WORLDVIEW_ID) {
                    drawNetDepthLetter(graphics, 0);
                } else if (playerBoat == SLOOP_WORLDVIEW_ID) {
                    drawNetDepthLetter(graphics, 0);
                    drawNetDepthLetter(graphics, 1);
                }
            }
        } else {
            return null;
        }

       ShoalData shoal = plugin.getNearestShoal();
       if (shoal != null && shoal.getDepth() != ShoalData.ShoalDepth.UNKNOWN)
       {
           int desired = ShoalData.ShoalDepth.asInt(shoal.getDepth());
           if (desired < 1) {
               return null;
           }

           for (int netIndex = 0; netIndex < playerBoat - 1; netIndex++)
           {
               int current = Net.NetDepth.asInt(plugin.netList[netIndex].getNetDepth());
               if (current <= 0 || current == desired) {
                   continue;
               }
               if (config.showNetWidgetHint()) {
                   Direction direction = current < desired ? Direction.DOWN : Direction.UP;
                   highlightNetButton(graphics, netIndex, direction);
               }
           }
       }
        return null;
    }

    private void highlightNetButton(Graphics2D g, int netIndex, Direction direction)
    {
        Widget parent = client.getWidget(SAILING_SIDEPANEL_GROUP , FACILITIES_CONTENT_CLICKLAYER_CHILD);
        if (parent == null) return;

        Integer shipType = getPlayerBoatType();
        if (shipType == null) return;

        int childId = -1;
        if (netIndex == 0) {
            if (shipType == SKIFF_WORLDVIEW_ID) {
                childId = direction == Direction.DOWN ? SKIFF_DOWN_INDEX : SKIFF_UP_INDEX;
            } else if (shipType == SLOOP_WORLDVIEW_ID){
                childId = direction == Direction.DOWN ? STARBOARD_DOWN_INDEX : STARBOARD_UP_INDEX;
            }
        } else if (netIndex == 1) {
            childId = direction == Direction.DOWN ? PORT_DOWN_INDEX : PORT_UP_INDEX;
        } else {
            return;
        }

        Widget canvas = client.getWidget(SAILING_SIDEPANEL_GROUP, 5);
        if (canvas == null) return;

        Rectangle canvasBounds = canvas.getBounds();

        Widget button = parent.getChild(childId);
        if (button == null || button.isHidden()) return;

        Rectangle bounds = button.getBounds();
        if (bounds == null || bounds.width <= 0 || bounds.height <= 0) return;
        if (!canvasBounds.intersects(button.getBounds())) return;

        g.setColor(new Color(config.uiHighlightColour().getRed(), config.uiHighlightColour().getGreen(), config.uiHighlightColour().getBlue(), 120));
        g.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 8, 8);

        g.setColor(new Color(config.uiHighlightColour().getRed(), config.uiHighlightColour().getGreen(), config.uiHighlightColour().getBlue(), 220));
        g.setStroke(new BasicStroke(2));
        g.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 8, 8);


    }

    private void drawNetDepthLetter(Graphics2D graphics, int netIndex) {
        int downId = -1;

        Widget parent = client.getWidget(SAILING_SIDEPANEL_GROUP , FACILITIES_CONTENT_CLICKLAYER_CHILD);
        if (parent == null) return;

        Integer shipType = getPlayerBoatType();
        if (shipType == null) return;

        if (shipType == SLOOP_WORLDVIEW_ID) {
            downId = (netIndex == 0) ? STARBOARD_DOWN_INDEX : PORT_DOWN_INDEX;
        } else if (shipType == SKIFF_WORLDVIEW_ID) {
            downId = SKIFF_DOWN_INDEX;
        }
        if (downId < 0) { return; }

        Widget down = parent.getChild(downId);

        Widget canvas = client.getWidget(SAILING_SIDEPANEL_GROUP, 5);
        if (canvas == null) return;

        Rectangle canvasBounds = canvas.getBounds();

        if (down == null || down.isHidden())
        {
            return;
        }

        Rectangle downButton = down.getBounds();

        if (downButton == null || downButton.width <= 0 || downButton.height <= 0)
        {
            return;
        }
        if (!canvasBounds.intersects(downButton)) return;

        Net net = plugin.netList[netIndex];
        if (net == null)
        {
            return;
        }

        String letter = depthLetter(net.getNetDepth());

        int targetX = downButton.x - 39;                  // left of the down button (magic number)
        int targetY = downButton.y;                       // halfway towards the up button (if dy=0, stays on down)

        // Draw the label with a background pill
        graphics.setFont(FontManager.getRunescapeBoldFont().deriveFont( 14f));
        FontMetrics fm = graphics.getFontMetrics();

        int textW = fm.stringWidth(letter);
        int textH = fm.getAscent();

        int x = targetX - textW / 2 + downButton.width / 2;  // center-ish relative to down button width
        int y = targetY + downButton.height / 2 + textH / 2 - 2;

        int padX = 6;
        int padY = 4;

        int bgW = textW + padX * 2;
        int bgH = fm.getHeight() + padY * 2;

        int bgX = x - padX;
        int bgY = y - fm.getAscent() - padY;

        graphics.setColor(new Color(0, 0, 0, 160));
        graphics.fillRoundRect(bgX, bgY, bgW, bgH, 10, 10);

        graphics.setColor(colorForDepth(net.getNetDepth()));
        graphics.drawString(letter, x, y);
    }

    private static String depthLetter(Net.NetDepth d)
    {
        switch (d)
        {
            case RAISED:  return "R";
            case SHALLOW: return "S";
            case MEDIUM:  return "M";
            case DEEP:    return "D";
            default:      return "?";
        }
    }

    private static Color colorForDepth(Net.NetDepth d)
    {
        switch (d)
        {
            case RAISED:  return new Color(200, 200, 200);
            case SHALLOW: return new Color(80, 255, 80);
            case MEDIUM:  return new Color(255, 200, 80);
            case DEEP:    return new Color(255, 80, 80);
            default:      return Color.WHITE;
        }
    }
}

package com.deepseatrawling;

import net.runelite.client.ui.overlay.infobox.InfoBox;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.AbstractMap;
import java.util.LinkedHashMap;
import java.util.Map;

public class TrawlingNetInfoBox extends InfoBox {
    private final DeepSeaTrawling plugin;
    private final DeepSeaTrawlingConfig config;

    public TrawlingNetInfoBox(BufferedImage image, DeepSeaTrawling plugin, DeepSeaTrawlingConfig config)
    {
        super(image, plugin);
        this.plugin = plugin;
        this.config = config;
    }

    @Override
    public boolean render()
    {
        return (plugin.fishQuantity > 0 && config.infoboxIsEnabled());
    }

    @Override
    public String getText()
    {
        return String.valueOf(plugin.fishQuantity);
    }

    @Override
    public String getTooltip()
    {
        // Aggregate queue by fish type for display
        LinkedHashMap<String, Integer> byType = new LinkedHashMap<>();
        for (AbstractMap.SimpleEntry<String, Integer> entry : plugin.netQueue)
        {
            byType.merge(entry.getKey(), entry.getValue(), Integer::sum);
        }

        if (byType.isEmpty())
        {
            return "Fish in nets: " + plugin.fishQuantity;
        }

        StringBuilder sb = new StringBuilder("Fish in nets: ").append(plugin.fishQuantity);
        for (Map.Entry<String, Integer> entry : byType.entrySet())
        {
            sb.append("</br>").append(entry.getKey()).append(": ").append(entry.getValue());
        }
        return sb.toString();
    }

    @Override
    public Color getTextColor()
    {
        return config != null
                ? config.fishCounterTextColour()
                : Color.WHITE;
    }

}

package com.deepseatrawling;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumMap;

@Slf4j
@Singleton
public class NetActivityTracker
{
    @Inject
    private Client client;

    @Inject
    private DeepSeaTrawlingConfig config;

    @Inject
    private Notifier notifier;

    public final EnumMap<TrawlingNetSide, GameObject> netObjects = new EnumMap<>(TrawlingNetSide.class);

    // GameObject of most recently-used net 
    @Getter
    private GameObject kickedNetObject = null;
    private TrawlingNetSide lastUsedNetSide = null;

    @Getter
    private boolean kickHighlightActive = false;
    private boolean facilitiesReEnabled = false;
    private Integer lastBoatMoveMode = null;


    public void onKicked()
    {
        kickHighlightActive = true;
        log.debug("Kick highlight activated: kickedNetObject={}",
                kickedNetObject != null ? kickedNetObject.getId() : "null");
    }

    public void reset()
    {
        netObjects.clear();
        kickedNetObject = null;
        lastUsedNetSide = null;
        kickHighlightActive = false;
        facilitiesReEnabled = false;
        lastBoatMoveMode = null;
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        GameObject obj = event.getGameObject();
        if (obj == null || obj.getWorldView() == null) return;

        TrawlingNetSide side = TrawlingNetSide.fromGameObjectId(obj.getId());
        if (side == null) return;

        netObjects.put(side, obj);
        if (kickedNetObject == null && side == lastUsedNetSide) {
            kickedNetObject = obj;
        }
        backfillLastUsedNet();
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        GameObject obj = event.getGameObject();
        if (obj == null) return;
        netObjects.values().remove(obj);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != net.runelite.api.ChatMessageType.GAMEMESSAGE) return;
        String msg = event.getMessage().replaceAll("<[^>]*>", "");
        if (msg.contains("This boat's facilities have been enabled again"))
        {
            facilitiesReEnabled = true;
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged e)
    {
        // clear highlight when the player starts using any facility
        if (e.getVarbitId() == VarbitID.SAILING_BOAT_FACILITY_LOCKEDIN && e.getValue() != 0)
        {
            kickHighlightActive = false;
        }

        if (e.getVarbitId() == VarbitID.SAILING_SIDEPANEL_BOAT_MOVE_MODE)
        {
            int newMode = e.getValue();
            if (lastBoatMoveMode != null && lastBoatMoveMode == 4 && newMode != 4 && facilitiesReEnabled
                    && kickedNetObject != null
                    && client.getVarbitValue(VarbitID.SAILING_BOAT_FACILITY_LOCKEDIN) == 0)
            {
                facilitiesReEnabled = false;
                if (config.notifyKickedFromNet().isEnabled()) {
                    kickHighlightActive = true;
                    notifier.notify(config.notifyKickedFromNet(), "The captain is back on board! Operate your net.");
                }
            }
            lastBoatMoveMode = newMode;
        }

        if (e.getVarbitId() != VarbitID.SAILING_FACILITY_HOTSPOT_NUMBER) return;
        if (e.getValue() == 0) return;

        int hotspotId = e.getValue()-1;
        int net0Hotspot = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_0_HOTSPOT_ID);
        int net1Hotspot = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_1_HOTSPOT_ID);

        if (net0Hotspot != 0 && hotspotId == net0Hotspot) {
            lastUsedNetSide = TrawlingNetSide.STARBOARD;
            GameObject net = netObjects.get(TrawlingNetSide.STARBOARD);
            if (net != null) kickedNetObject = net;
        } else if (net1Hotspot != 0 && hotspotId == net1Hotspot) {
            lastUsedNetSide = TrawlingNetSide.PORT;
            GameObject net = netObjects.get(TrawlingNetSide.PORT);
            if (net != null) kickedNetObject = net;
        }
    }

    // call if a player was already using a net when the plugin is loaded, like a fresh install
    private void backfillLastUsedNet()
    {
        if (kickedNetObject != null) return;
        int currentHotspot = client.getVarbitValue(VarbitID.SAILING_FACILITY_HOTSPOT_NUMBER);
        if (currentHotspot == 0) return;

        // subtract 1 to match the hotspot ID varbits which are 1-indexed 
        currentHotspot = currentHotspot - 1;
        int net0Hotspot = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_0_HOTSPOT_ID);
        int net1Hotspot = client.getVarbitValue(VarbitID.SAILING_SIDEPANEL_BOAT_TRAWLING_NET_1_HOTSPOT_ID);
        if (net0Hotspot != 0 && currentHotspot == net0Hotspot) {
            lastUsedNetSide = TrawlingNetSide.STARBOARD;
            GameObject net = netObjects.get(TrawlingNetSide.STARBOARD);
            if (net != null) kickedNetObject = net;
        } else if (net1Hotspot != 0 && currentHotspot == net1Hotspot) {
            lastUsedNetSide = TrawlingNetSide.PORT;
            GameObject net = netObjects.get(TrawlingNetSide.PORT);
            if (net != null) kickedNetObject = net;
        }
    }
}

package com.deepseatrawling;

import lombok.Getter;
import net.runelite.api.gameval.ObjectID;

@Getter
public enum TrawlingNetSide
{
    STARBOARD(new int[]{
        ObjectID.SAILING_ROPE_TRAWLING_NET_3X8_STARBOARD,
        ObjectID.SAILING_LINEN_TRAWLING_NET_3X8_STARBOARD,
        ObjectID.SAILING_HEMP_TRAWLING_NET_3X8_STARBOARD,
        ObjectID.SAILING_COTTON_TRAWLING_NET_3X8_STARBOARD,
        ObjectID.SAILING_ROPE_TRAWLING_NET,
        ObjectID.SAILING_LINEN_TRAWLING_NET,
        ObjectID.SAILING_HEMP_TRAWLING_NET,
        ObjectID.SAILING_COTTON_TRAWLING_NET,
    }),
    PORT(new int[]{
        ObjectID.SAILING_ROPE_TRAWLING_NET_3X8_PORT,
        ObjectID.SAILING_LINEN_TRAWLING_NET_3X8_PORT,
        ObjectID.SAILING_HEMP_TRAWLING_NET_3X8_PORT,
        ObjectID.SAILING_COTTON_TRAWLING_NET_3X8_PORT,
    });

    private final int[] gameObjectIds;

    TrawlingNetSide(int[] gameObjectIds)
    {
        this.gameObjectIds = gameObjectIds;
    }

    public static TrawlingNetSide fromGameObjectId(int id)
    {
        for (TrawlingNetSide side : values())
        {
            for (int objectId : side.gameObjectIds)
            {
                if (objectId == id)
                {
                    return side;
                }
            }
        }
        return null;
    }
}

package com.deepseatrawling;

import net.runelite.client.ui.overlay.infobox.InfoBox;

import java.awt.*;
import java.awt.image.BufferedImage;

public class FishCatchInfoBox extends InfoBox {
    private final DeepSeaTrawling plugin;
    private final DeepSeaTrawlingConfig config;
    private final String fishName;
    private int count;
    private int holdCount;
    private int inventoryCount;

    public FishCatchInfoBox(BufferedImage image, DeepSeaTrawling plugin, DeepSeaTrawlingConfig config, String fishName)
    {
        super(image, plugin);
        this.plugin = plugin;
        this.config = config;
        this.fishName = fishName;
        this.count = 0;
        this.holdCount = 0;
    }

    public void incrementCount(int amount)
    {
        this.count += amount;
    }

    public void decrementCount(int amount)
    {
        this.count = Math.max(0, this.count - amount);
    }

    public void incrementHoldCount(int amount)
    {
        this.holdCount += amount;
    }

    public void incrementInventoryCount(int amount)
    {
        this.inventoryCount += amount;
    }

    public void resetCount()
    {
        this.count = 0;
        this.holdCount = 0;
        this.inventoryCount = 0;
    }

    public int getCount()
    {
        return count;
    }

    public int getHoldCount()
    {
        return holdCount;
    }

    public int getInventoryCount()
    {
        return inventoryCount;
    }

    @Override
    public String getText()
    {
        return String.valueOf(count);
    }

    @Override
    public boolean render()
    {
        return (count > 0 && config.infoboxFishTypeEnabled());
    }

    @Override
    public String getTooltip()
    {
        return "Total " + fishName + ": " + count + "</br>Sent to cargo: " + holdCount;
    }

    @Override
    public Color getTextColor()
    {
        return config != null
                ? config.fishCounterTextColour()
                : Color.WHITE;
    }
}

