	private static final Map<String, Integer> WORD_NUMBERS = Map.ofEntries(
			Map.entry("a", 1),
			Map.entry("one", 1),
			Map.entry("two", 2),
			Map.entry("three", 3),
			Map.entry("four", 4),
			Map.entry("five", 5),
			Map.entry("six", 6),
			Map.entry("seven", 7),
			Map.entry("eight", 8),
			Map.entry("nine", 9),
			Map.entry("ten", 10)
	);

	private int convertToNumber(String s)
	{
		s = s.toLowerCase();

		Integer v = WORD_NUMBERS.get(s);
		if (v != null)
		{
			return v;
		}

		throw new IllegalArgumentException("Unknown quantity: " + s);
	}
